+import org.springframework.stereotype.Service;
+import org.springframework.transaction.annotation.Transactional;
+
+@Service
+@RequiredArgsConstructor
+public class ReservationService {
+    private final EventRepository events;
+    private final ReservationRepository reservations;
+
+    @Transactional
+    public Reservation reserve(Long eventId, Long memberId, int quantity) {
+        Event event = events.findById(eventId).orElseThrow();
+        if (event.getRemainingSeats() < quantity) throw new SoldOutException();
+        event.decreaseSeats(quantity);
+        return reservations.save(new Reservation(event.getId(), memberId, quantity));
+    }
+}

