@@ -0,0 +1,19 @@
+package com.eventpass.reservation;
+
+import lombok.RequiredArgsConstructor;
+import org.springframework.web.bind.annotation.*;
+
+@RestController
+@RequiredArgsConstructor
+public class ReservationController {
+    private final ReservationService service;
+
+    @PostMapping("/api/events/{eventId}/reservations")
+    public CreatedResponse create(@PathVariable Long eventId, @RequestBody ReservationRequest request) {
+        Reservation saved = service.reserve(eventId, request.memberId(), request.quantity());
+        return new CreatedResponse(saved.getId());
+    }
+
+    public record ReservationRequest(Long memberId, int quantity) {}
+    public record CreatedResponse(Long reservationId) {}
+}

