--- a/frontend/src/features/reservation/EventReservationPanel.tsx
+++ b/frontend/src/features/reservation/EventReservationPanel.tsx
@@ -1,2 +1,24 @@
-export function FeaturePanel() { return null; }
-// 화면 구현 예정
+import { useState } from 'react';
+import { api } from '../../lib/api';
+
+type Props = { eventId: number; memberId: number; reload: () => Promise<void> };
+
+export function EventReservationPanel({ eventId, memberId, reload }: Props) {
+  const [quantity, setQuantity] = useState(1);
+  const [error, setError] = useState('');
+  async function submit() {
+    setError('');
+    try {
+      await api.post(`/api/events/${eventId}/reservations`, { memberId, quantity });
+      await reload();
+    } catch {
+      setError('요청을 처리하지 못했습니다. 잠시 후 다시 시도해주세요.');
+    }
+  }
+  return <section>
+    <h2>행사 좌석 예약</h2>
+    <label>예약 인원<input type="number" value={quantity} onChange={e => setQuantity(Number(e.target.value))} /></label>
+    {error && <p role="alert">{error}</p>}
+    <button onClick={submit}>저장하기</button>
+  </section>;
+}

