+package com.eventpass.reservation;
+
+import java.util.Optional;
+import org.junit.jupiter.api.Test;
+import static org.assertj.core.api.Assertions.assertThat;
+import static org.mockito.Mockito.*;
+
+class ReservationServiceTest {
+    @Test
+    void returnsCreatedRecordForValidRequest() {
+        var events = mock(EventRepository.class);
+        var reservations = mock(ReservationRepository.class);
+        var resource = mock(Event.class);
+        when(events.findById(1L)).thenReturn(Optional.of(resource));
+        when(resource.getId()).thenReturn(1L);
+        when(resource.getRemainingSeats()).thenReturn(3);
+        when(reservations.save(any(Reservation.class))).thenAnswer(invocation -> invocation.getArgument(0));
+        var service = new ReservationService(events, reservations);
+        var saved = service.reserve(1L, 7L, 2);
+        assertThat(saved).isNotNull();
+        verify(reservations).save(any(Reservation.class));
+    }
+}
